<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><form class="form-card" method="post" action="<?= base_url('admin/orders/'.$row['id'].'/status') ?>"><?= csrf_field() ?><label>Status<select name="status"><?php foreach(['pending','processing','shipped','delivered','cancelled'] as $s): ?><option <?= $row['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></label><button class="btn">Update</button></form><div class="table-wrap" style="margin-top:25px"><table><tr><th>Item</th><th>Quantity</th><th>Price</th></tr><?php foreach($items as $i): ?><tr><td><?= esc($i['product_name']) ?></td><td><?= $i['quantity'] ?></td><td>₹<?= number_format($i['price_at_purchase'],2) ?></td></tr><?php endforeach ?></table></div><?= $this->endSection() ?>
